    4: <int>[1, 3],
  };

  final int numPages = graph.length;
  const double dampingFactor = 0.85;
  const int maxIterations = 100;
  const double convergenceThreshold = 0.0001;

  Map<int, double> pageRank = <int, double>{
    for (final int page in graph.keys) page: 1.0 / numPages,
  };

