  for (int iteration = 1; iteration <= maxIterations; iteration++) {
    final double danglingMass = pageRank.entries
        .where((entry) => graph[entry.key]!.isEmpty)
        .fold<double>(0.0, (sum, entry) => sum + entry.value);

    final Map<int, double> newPageRank = <int, double>{
      for (final int page in graph.keys)
        page: (1.0 - dampingFactor) / numPages +
            dampingFactor * danglingMass / numPages,
    };

    graph.forEach((source, targets) {
      if (targets.isNotEmpty) {
        final double contribution = pageRank[source]! / targets.length;
        for (final int target in targets) {
          newPageRank[target] =
              newPageRank[target]! + dampingFactor * contribution;
        }
      }
    });

    double maxDifference = 0.0;
    newPageRank.forEach((page, value) {
      final double difference = (value - pageRank[page]!).abs();
      if (difference > maxDifference) {
        maxDifference = difference;
      }
